{
  "judgments": [
    {
      "proposal_id": "P0000",
      "source_refs": [
        "F001",
        "F002",
        "F005"
      ],
      "rationale": "Proposal P0000 correctly preserves all core components of paragraph (2) (actor, modal force, threshold, and conditions) while resolving the outgoing reference to 'the attendance fee' defined in paragraph (1) and accounting for the related certification provision in paragraph (5). All added components and context quotes faithfully reflect the source text, making this a complete and necessary correction.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0001",
      "source_refs": [
        "F002"
      ],
      "rationale": "Proposal P0001 alters the modal force from discretionary ('may be paid, in the discretion of the trial judge') to mandatory ('must be paid, without trial-judge discretion'), directly contradicting the source text in paragraph (2).",
      "verdict": "unsupported"
    },
    {
      "proposal_id": "P0002",
      "source_refs": [
        "F001",
        "F002"
      ],
      "rationale": "The unchanged draft C0002 leaves the outgoing reference to 'the attendance fee' unexplained despite paragraph (1) providing its governing definition and rate ($50 per day). Leaving the statement without an explanation of this referenced governing meaning constitutes a detectable omission.",
      "verdict": "unsupported"
    }
  ]
}
